parameters.jsCode:
// Exnoria - prd.feedback.log
// Build enriched feature request payload for HubSpot product feedback pipeline
// No contact-facing action — internal logging only

const webhook = $("Webhook").first().json.body;
const contact = $input.first().json;

const { contact_id, signal_id, signal_severity, interventions } = webhook;
const feature_request = webhook.payload?.feature_request ?? webhook.feature_request ?? 'No description provided';

const firstname = contact.properties?.firstname?.value ?? 'Contact';
const lastname  = contact.properties?.lastname?.value  ?? '';
const email     = contact.properties?.email?.value     ?? '';
const company   = contact.properties?.company?.value   ?? '';

const loggedAt = new Date(new Date().setUTCHours(0,0,0,0)).getTime();

const ticketTitle = '[Feature Request] ' + feature_request.substring(0, 80);

const enrichedNote = [
  'Signal: ' + signal_id + ' (severity: ' + signal_severity + ')',
  'Contact: ' + firstname + ' ' + lastname + (company ? ' — ' + company : ''),
  'Email: ' + email,
  'Contact ID: ' + contact_id,
  '',
  'Feature request:',
  feature_request,
  '',
  'Compass interventions: ' + (interventions || []).join(', ')
].join('\n');

return [{
  json: {
    contact_id,
    signal_id,
    signal_severity,
    email,
    firstname,
    lastname,
    company,
    feature_request,
    ticket_title: ticketTitle,
    enriched_note: enrichedNote,
    logged_at: loggedAt
  }
}];

// Simulate -- HubSpot ticket/deal creation in product feedback pipeline
// Replace with real HubSpot API when pipeline is configured

const data = $("Code -- feedback logic").first().json;

return [{
  json: {
    ...data,
    feedback_logged: true,
    ticket_id: 'feedback_sim_' + Date.now(),
    simulated: true
  }
}];

